jwt=h.api(h.PREFIX+'/upload-token')['jwt'];hashes=list(set(manifest.values()));missing=set(h.api('/pages/assets/check-missing',{'hashes':hashes},token=jwt));files={v:f for f,v in manifest.items()if v in missing};assert set(files.values()).issubset(allowed)
print(json.dumps({'preflight':'passed','changed_assets':sorted(allowed),'backend_unchanged':True,'policy_date':'2026-11-19'}),flush=True)
if not args.activate:raise SystemExit(0)
assert not subprocess.check_output(['git','status','--porcelain'],cwd=ROOT).strip();commit=subprocess.check_output(['git','rev-parse','HEAD'],cwd=ROOT,text=True).strip();assert commit==subprocess.check_output(['git','ls-remote','origin','refs/heads/main'],cwd=ROOT,text=True).split()[0]
for key,f in files.items():h.api('/pages/assets/upload',[{'key':key,'value':base64.b64encode((RELEASE/'assets'/f.lstrip('/')).read_bytes()).decode(),'metadata':{'contentType':mimetypes.guess_type(f)[0]or'application/octet-stream'},'base64':True}],token=jwt)
h.api('/pages/assets/upsert-hashes',{'hashes':hashes},token=jwt);assert not h.api('/pages/assets/check-missing',{'hashes':hashes},token=jwt)
fields={'manifest':json.dumps(manifest),'branch':'main','commit_hash':commit,'commit_message':'Factual About and updated Privacy/Terms with matching PDFs','commit_dirty':'false','_worker.bundle':('_worker.bundle',bundle),'functions-filepath-routing-config.json':('functions-filepath-routing-config.json',(ROOT/'production/state/pages-function-routes.json').read_bytes()),'_routes.json':('_routes.json',json.dumps({'version':1,'include':['/*'],'exclude':[]}).encode())};body,content_type=h.multipart(fields);r=h.api(h.PREFIX+'/deployments',body,'POST',content_type=content_type)
record={'deployment_id':r['id'],'url':r['url'],'environment':r['environment'],'commit':commit,'baseline':current['deployment_id'],'checkout_changes':meta['changes'],'public_content_release':meta['public_content_release'],'backend_bundle_sha256':current['backend_bundle_sha256'],'database_migrations_applied':[]};pathlib.Path('/tmp/opus-public-content-result.json').write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'deployment_id':r['id'],'url':r['url']}))
